    Historico = apps.get_model("carga_org_lot", "HistoricoConjuntoLotacao")
    status_map = {
        "AGUARDANDO_REVISAO": "COM_PENDENCIAS",
        "INCORPORADA": "PRONTO_PARA_HOMOLOGACAO",
    }
    imports = Importacao.objects.filter(
        idtipocarga_id__in=[4, 5],
        idimportacaoorganograma_id__isnull=False,
        idconjuntolotacao_id__isnull=True,
    ).iterator()
    for importacao in imports:
        set_status = status_map.get(importacao.strstatusimportacao, "EM_VALIDACAO")
        conjunto = Conjunto.objects.create(
            idpatriarca_id=importacao.idpatriarca_id,
            idimportacaoorganograma_id=importacao.idimportacaoorganograma_id,
            strreferencia=(
                importacao.strreferencia
                or f"Histórico da importação {importacao.pk}"
            ),
            strsituacao=set_status,
            created_by_id=importacao.created_by_id,
            created_by_name=importacao.created_by_name,
            updated_by_id=importacao.updated_by_id,
            updated_by_name=importacao.updated_by_name,
        )
        importacao.idconjuntolotacao_id = conjunto.pk
        importacao.strtipooperacaolotacao = "INICIAL"
        importacao.save(
            update_fields=["idconjuntolotacao", "strtipooperacaolotacao"]
        )
        Historico.objects.create(
            idconjuntolotacao_id=conjunto.pk,
            stracao="HISTORICO_MIGRADO",
            strsituacaoanterior="",
            strsituacaonova=set_status,
            strmensagem="Conjunto criado a partir de importação preexistente.",
            jsondetalhes={"idimportacaoplanilha": importacao.pk},
            created_by_id=importacao.created_by_id,
            created_by_name=importacao.created_by_name,
            updated_by_id=importacao.updated_by_id,
            updated_by_name=importacao.updated_by_name,
        )


